package org.kanger.storage.dumb2;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.kanger.*;
import org.kanger.ContextSignedCandidateInspection.*;
import org.kanger.storage.dumb2.ContextNativeCandidateLeaseMatrix.Fixture;
import org.kanger.storage.dumb2.ContextNativeCandidateLeaseMatrix.State;
final class ContextSignedCandidateLeaseMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean bad=false;try{a.run();}catch(Exception expected){bad=true;}require(bad,why);}
 static Limits limits(){return new Limits(64,8,2,16,WORK,500000,WORK,WORK,64);}
 static RevisionRef create(Path d,String name,String text)throws Exception{return ContextNativeCandidateLeaseMatrix.create(d,name,text);}
 static void yes(Result r){require(r.status==Status.QUIESCENT_SUPPLIED&&r.candidate!=null&&r.oppositions.isEmpty(),r.phase+": "+r.reason);}
 static void no(Result r,String phase){require(r.status==Status.INCOMPLETE&&r.candidate==null&&r.oppositions.isEmpty()&&r.baseContext==null&&r.foreignFingerprints.isEmpty()&&r.phase.equals(phase),r.phase+": "+r.reason);}
 static void positive()throws Exception{Path d=Files.createTempDirectory("signed-candidate-lease-");create(d,"A","!$u seed(u)&&~blocked(u);");
  try(Fixture x=new Fixture(d,"X")){require(x.mind.compile("!anchor(1);",null,false),"X anchor");x.db.connectContext("A");State before=new State(x);Limits l=limits();
   try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(x.db,x.mind,l.rows)){ContextProductionSnapshotSession.Inventory inventory=lease.inventory();Result stable=lease.inspectSignedCandidate("!@u seed(u)->~blocked(u);",l);yes(stable);require(stable.baseContext.equals(x.db.getContextId())&&stable.baseRevision==before.revision&&stable.baseFingerprint.equals(inventory.x.fingerprint),"actual owning X identity/revision/inventory");require(stable.foreignFingerprints.equals(Collections.singletonList(inventory.foreign.get(0).fingerprint)),"exact signed initialized pinned foreign view");Result clash=lease.inspectSignedCandidate("!@u seed(u)->blocked(u);",l);require(clash.status==Status.REFUTED&&clash.candidate!=null&&!clash.oppositions.isEmpty(),clash.phase+": "+clash.reason);for(Opposition o:clash.oppositions){System.out.println("SIGNED_LEASE_PROOF initial="+o.initial+" transitions="+o.recordedTransitions+" use="+o.usesCandidate+" x="+o.xRefuted+" foreign="+o.foreignRefuted+" depth="+o.depth+" sources="+o.originalSources.size());require(o.initial&&o.recordedTransitions==0&&o.usesCandidate&&(o.xRefuted||o.foreignRefuted)&&o.depth==2,"actual two-step signed empty proof flags/depth/candidate use");require(o.originalSources.size()==2&&o.originalSources.contains(clash.candidate)&&o.targetContexts.size()==1,"exact candidate+physical signed bundle Sources and target");}reject(()->clash.oppositions.get(0).originalSources.clear(),"immutable proof provenance");reject(()->stable.foreignFingerprints.clear(),"immutable historical metadata");lease.requireCurrent();before.unchanged(x);require(true,"positive and refuted diagnostics preserve active caller/revision/all stores");}
   yes(x.db.inspectSignedProductionCandidate(x.mind,"!$u extra(u)&&~absent(u);",l));before.unchanged(x);require(ContextProductionInventory.inspect(x.mind,x.db.getContextId(),x.db.getRevision(),true,Collections.emptyList(),64).primary.stream().noneMatch(row->row.origin.contains("extra(")),"public diagnostic never publishes candidate primary");}
  System.out.println("SIGNED_CANDIDATE_LEASE_POSITIVE exactSignedOwningViews=true initialSourceProof=true newSignedCandidate=true callerUnchanged=true historicalMetadataOnly=true");
 }
 static void freshness()throws Exception{Path d=Files.createTempDirectory("signed-candidate-fresh-");RevisionRef old=create(d,"A","!$u seed(u)&&~blocked(u);");create(d,"B","!b(1);");Limits l=limits();
  try(Fixture x=new Fixture(d,"X")){require(x.mind.compile("!anchor(1);",null,false),"X anchor");x.db.connectContext("A");x.db.connectContext("B");Result historical;
   try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(x.db,x.mind,64)){historical=lease.inspectSignedCandidate("!trial(1);",l);yes(historical);RevisionRef newer=create(d,"A","!later(8);");require(newer.getRevision()>old.getRevision(),"foreign HEAD advanced");lease.requireCurrent();Result pinned=lease.inspectSignedCandidate("!trial(1);",l);yes(pinned);require(pinned.foreignFingerprints.equals(historical.foreignFingerprints)&&lease.inventory().foreign.get(0).revision==old.getRevision(),"unchanged old pin remains valid and never sees newer HEAD");}
   ContextProductionSnapshotSession initialized=ContextProductionSnapshotSession.open(x.db,x.mind,64);x.db.applyConnectionCommand(x.mind,"A","!private(4);");reject(()->initialized.inspectSignedCandidate("!trial(1);",l),"private initialization invalidates old lease");initialized.close();Result fresh=x.db.inspectSignedProductionCandidate(x.mind,"!trial(1);",l);yes(fresh);require(!fresh.foreignFingerprints.get(0).equals(historical.foreignFingerprints.get(0)),"fresh request sees actual new initialization");
   try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(x.db,x.mind,64)){require(x.mind.compile("!~trial(1);",null,false),"actual X changed");reject(()->lease.inspectSignedCandidate("!trial(1);",l),"changed X invalidates previous lease");}require(historical.status==Status.QUIESCENT_SUPPLIED&&x.db.inspectSignedProductionCandidate(x.mind,"!trial(1);",l).status!=Status.QUIESCENT_SUPPLIED,"historical success cannot approve candidate against new X");
   try(ContextProductionSnapshotSession topology=ContextProductionSnapshotSession.open(x.db,x.mind,64)){x.db.disconnectContext("B");reject(()->topology.inspectSignedCandidate("!extra(2);",l),"topology removal invalidates complete request");}
   ContextProductionSnapshotSession closed=ContextProductionSnapshotSession.open(x.db,x.mind,64);closed.close();reject(()->closed.inspectSignedCandidate("!extra(2);",l),"closed lease");
   try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(x.db,x.mind,64)){AtomicBoolean refused=new AtomicBoolean();Thread t=new Thread(()->{try{lease.inspectSignedCandidate("!extra(2);",l);}catch(Exception expected){refused.set(true);}});t.start();t.join();require(refused.get(),"owner thread required");Mind other=new Mind(x.user);x.user.setCurrentMind(other);try{reject(()->lease.inspectSignedCandidate("!extra(2);",l),"actual active caller required");}finally{x.user.setCurrentMind(x.mind);}lease.requireCurrent();}
   Mind pending=new Mind(x.mind);try{reject(()->x.db.inspectSignedProductionCandidate(x.mind,"!extra(2);",l),"pending child cannot borrow settled-root lease");}finally{x.mind.release(pending);}reject(()->x.db.inspectSignedProductionCandidate(new Mind(new User()),"!extra(2);",l),"unrelated Mind has no owning provider");
   x.db.connectContext("B","own");reject(()->x.db.inspectSignedProductionCandidate(x.mind,"!extra(2);",l),"existing TRUST lease refusal retained, no flattening");x.db.disconnectContext("B");yes(x.db.inspectSignedProductionCandidate(x.mind,"!extra(2);",l));}
  System.out.println("SIGNED_CANDIDATE_LEASE_FRESHNESS oldPinHeadIndependence=true initializedAndXChanges=true topologyThreadCallerClosedAndPending=true trustFailsClosed=true");
 }
 static void boundary()throws Exception{Path d=Files.createTempDirectory("signed-candidate-boundary-");create(d,"A","!$u seed(u)&&~blocked(u);");Limits l=limits();long revision;
  try(Fixture x=new Fixture(d,"X")){require(x.mind.compile("!anchor(1);",null,false),"X anchor");x.db.connectContext("A");State before=new State(x);try(ContextProductionSnapshotSession lease=ContextProductionSnapshotSession.open(x.db,x.mind,64)){reject(()->lease.inspectSignedCandidate("!extra(2);",new Limits(63,8,2,16,WORK,500000,WORK,WORK,64)),"row policy cannot replace owning lease");no(lease.inspectSignedCandidate("!@u p(u)||q(u);",l),"signed-candidate");no(lease.inspectSignedCandidate("!extra(2);",new Limits(64,8,2,16,WORK,500000,WORK,1,64)),"signed-candidate-audit");no(lease.inspectSignedCandidate("!@u seed(u)->blocked(u);",new Limits(64,8,2,16,WORK,500000,WORK,1,64)),"signed-candidate-audit");yes(lease.inspectSignedCandidate("!extra(2);",l));lease.requireCurrent();before.unchanged(x);require(true,"failed diagnostics do not consume lease or modify stores");}reject(()->x.db.inspectSignedProductionCandidate(x.mind,"!extra(2);",new Limits(1,8,2,16,WORK,500000,WORK,WORK,64)),"complete capture row limit");reject(()->x.db.inspectSignedProductionCandidate(x.mind,"!extra(2);",null),"explicit policy required");revision=x.db.getRevision();}
  try(Fixture historical=new Fixture(d,"X@"+revision)){require(historical.db.isReadOnly(),"historical provider read-only");State before=new State(historical);yes(historical.db.inspectSignedProductionCandidate(historical.mind,"!extra(2);",l));before.unchanged(historical);require(true,"read-only diagnostic does not confer write eligibility");}
  System.out.println("SIGNED_CANDIDATE_LEASE_BOUNDARY finalAuditRequiredForBothVerdicts=true rowAndPolicyExact=true historicalReadOnly=true noWriteCapability=true");
 }
}
